const handleViewTimetable = () => {
    if (!selectedTeacher) return;
  
    setLoading(true);
    // Fetch timetable by teacher_id
    axios.get(`http://localhost:8000/api/timetable/?teacher_id=${selectedTeacher}`, {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(response => {
        console.log("API Response:", response); // Log the entire response
  
        // Log the data from the response
        console.log("Timetable Data:", response.data);
  
        if (response.data && response.data.length > 0) {
          // Initialize the formattedTimetable object with empty arrays for each day
          const formattedTimetable = { Monday: [], Tuesday: [], Wednesday: [], Thursday: [], Friday: [] };
  
          // Iterate through the timetable entries and assign subjects to the correct day/period
          response.data.forEach(entry => {
            const day = entry.day;
            const periodIndex = periods.indexOf(entry.time); // Find the index of the period
            if (day && periodIndex !== -1) {
              if (entry.is_lab) {
                // If it's a lab, fill two consecutive periods
                formattedTimetable[day][periodIndex] = entry.subject; // First slot
                if (periodIndex + 1 < periods.length) {
                  formattedTimetable[day][periodIndex + 1] = entry.subject; // Second slot
                }
              } else {
                // Regular class, assign to one slot
                formattedTimetable[day][periodIndex] = entry.subject;
              }
            }
          });
  
          // Check if formatted timetable has any data and log it
          console.log("Formatted Timetable:", formattedTimetable);
          setTimetable(formattedTimetable);
        } else {
          console.error("No timetable data received.");
        }
        setLoading(false);
      })
      .catch(error => {
        console.error('Error fetching timetable:', error);
        setLoading(false);
      });
  };
